"Abstand Anfang / Ende":"Відступ початок / кінець",
"Abstand Anfang / Ende macht aus der Lasche eine Teillasche. Weitere geschlossene Profile in der Skizze werden zu Ausschnitten in der Platte. Bohrungen und Fenster in einer Lasche: Mitte entlang der Kante (bei einer gebogenen Kante entlang des Bogens), Mitte ab Ende der Biegung, Größe – sie erscheinen auch in der Abwicklung. Geht eine gebogene Kante ohne Knick in ihre Nachbarkante über und haben beide eine Lasche mit gleichem Biegewinkel, laufen die Laschen ohne Freischnitt ineinander über. „Kontur aus Skizze“ schneidet die geschlossenen Profile einer Skizze aus der Lasche: ihr X läuft entlang der Kante, ihr Y in die Lasche hinein, der Nullpunkt liegt am Kantenanfang auf dem Ende der Biegung (verschiebbar).":"Відступ від початку / кінця робить із полиці часткову полицю. Інші замкнені профілі в ескізі стають вирізами в пластині. Отвори та вікна в полиці: центр уздовж ребра (на вигнутому ребрі – уздовж дуги), центр від кінця згину, розмір – вони з’являються й у розгортці. Якщо вигнуте ребро без зламу переходить у сусіднє ребро і на обох є полиця з однаковим кутом згину, полиці переходять одна в одну без розвантажувального вирізу. «Контур з ескіза» вирізає замкнені профілі ескіза з полиці: його X іде вздовж ребра, його Y – всередину полиці, нульова точка лежить на початку ребра в кінці згину (можна зсунути).",
