"Alle Flächen wählen, die verschwinden sollen (bei einer Tasche Wände und Boden, bei einer Bohrung die Wand, bei einer Verrundung die Rundung). Die Nachbarflächen werden über die Lücke verlängert. Der Schritt rechnet bei Änderungen am Körper mit; beim ersten Mal lädt dafür der große Geometriekern (einige Sekunden).":"Виберіть усі грані, які мають зникнути (для кишені – стінки та дно, для отвору – стінку, для скруглення – заокруглену грань). Сусідні грані подовжуються через утворений проміжок. Крок перераховується при змінах тіла; при першому запуску завантажується повне геометричне ядро (кілька секунд).",
