"Bei „Bohrungen“ sitzt das Teil bündig in dem Ende der Bohrung, das näher am Klickpunkt liegt. Mehrere Bohrungen nacheinander anklicken, dann „Fertig“.":"У режимі «Отвори» деталь сидить урівень у тому кінці отвору, що ближчий до точки клацання. Клацніть кілька отворів по черзі, потім «Готово».",
"Bei „Bohrungen“ sitzt der Kopf auf der Seite der Bohrung, die näher am Klickpunkt liegt; der Schaft zeigt in die Bohrung. Mehrere Bohrungen nacheinander anklicken, dann „Fertig“.":"У режимі «Отвори» головка розташовується з того боку отвору, що ближчий до точки клацання; стрижень спрямований в отвір. Клацніть кілька отворів по черзі, потім «Готово».",
