"Drehen: Elemente wählen, dann Drehpunkt anklicken und den Winkel mit der Maus zeigen (Vorschau); auch als Kopie":"Повернути: виберіть елементи, потім клацніть точку обертання й вкажіть кут мишею (попередній перегляд); також як копію",
