"Drehgeschwindigkeit":"Швидкість обертання",
"Drehmaschine mit Y-Achse: Schlüsselflächen, Konturen und Taschen auf der Planfläche fahren mit feststehendem Teil (C fest) in X und Y – genauer als die Polar-Interpolation. Was über den Y-Weg hinausgeht, bleibt bei der Polar-Interpolation.":"Токарний верстат з віссю Y: лиски під ключ, контури та кишені на торці виконуються при нерухомій деталі (C зафіксовано) по X і Y – точніше за полярну інтерполяцію. Те, що виходить за хід Y, залишається на полярній інтерполяції.",
