"Ebene Flächen des Körpers werden entlang ihrer Normalen extrudiert. Automatisch: nach außen = Material hinzufügen, nach innen (negativ) = ausschneiden.":"Плоскі грані тіла витискаються вздовж їхніх нормалей. Автоматично: назовні = додати матеріал, всередину (від’ємне) = вирізати.",
