"Ecken und Kantenenden rasten beim Anklicken ein. Punkte dienen als Bezug für Ebene durch drei Punkte und Achse durch zwei Punkte.":"Вершини та кінці ребер прив’язуються при клацанні. Точки слугують базою для площини через три точки та осі через дві точки.",
