"Eigene Kurzbefehle: in der Symbolleiste das Gruppenmenü (▾) öffnen, beim Befehl auf ⋮ klicken → „Tastaturkurzbefehl ändern …“.":"Власні скорочення: відкрийте меню групи (▾) на панелі інструментів, натисніть ⋮ біля команди → «Змінити гарячу клавішу …».",
"Eigene Maße und Hinweise lassen sich im Blatt mit der Maus ziehen (Abstand der Maßlinie, Winkel der Hinweislinie, Radius des Winkelbogens). Zwei Ecken anklicken = Längenmaß. Einen Kreisrand in der Draufsicht anklicken = Durchmesser (bzw. Radius). Winkel: erst die Ecke, dann je einen Eckpunkt auf beiden Schenkeln. Fase: beide Enden der schrägen Kante – ergibt z. B. 2×45°. Im Textfeld hinter jedem Maß steht ein Zusatz wie ±0,1, H7 oder 4×.":"Власні розміри та примітки можна перетягувати на аркуші мишею (відстань розмірної лінії, кут виносної лінії, радіус дуги кута). Клацніть два кути = лінійний розмір. Клацніть край кола на вигляді зверху = діаметр (або радіус). Кут: спочатку вершину, потім по точці на обох сторонах. Фаска: обидва кінці скошеного ребра – виходить, напр., 2×45°. У текстовому полі після кожного розміру стоїть додаток, як-от ±0,1, H7 або 4×.",
