"Erhebung braucht zwei Skizzen mit geschlossenen Profilen auf verschiedenen Ebenen.":"Для Loft потрібні два ескізи із замкненими профілями на різних площинах.",
"Erhebung braucht zwei Skizzen mit je einer Kurve (auf verschiedenen Ebenen).":"Для Loft потрібні два ескізи по одній кривій (на різних площинах).",
"Erhebung nicht möglich – Querschnitte prüfen (je ein geschlossenes Profil, nicht verdreht)":"Loft неможливий – перевірте перерізи (по одному замкненому профілю, без скручування)",
"Erhebung nicht möglich – je Skizze eine Kurve, gleiche Richtung, nicht verdreht":"Loft неможливий – по одній кривій на ескіз, однаковий напрямок, без скручування",
"Ersetzt den Standard-Kurzbefehl „{0}“.":"Замінює стандартну комбінацію «{0}».",
"Erst die Fläche an dem Körper anklicken, der bewegt wird, dann die Zielfläche am anderen Körper. Der Körper wird gedreht und verschoben, bis der erste Klickpunkt auf dem zweiten liegt und die Flächen aufeinander liegen.":"Спершу клацніть грань на тілі, яке переміщується, потім цільову грань на іншому тілі. Тіло повертається та переміщується, доки перша точка клацання не опиниться на другій, а грані не прилягатимуть одна до одної.",
"Erst die Kante an dem Körper anklicken, der bewegt wird, dann die Zielkante am anderen Körper. Gerade Kanten kommen deckungsgleich aufeinander (Mitte auf Mitte); bei Kreiskanten – Bohrung und Zapfen – werden die Achsen gleich gerichtet und die Mittelpunkte zusammengelegt.":"Спершу клацніть ребро на тілі, яке переміщується, потім цільове ребро на іншому тілі. Прямі ребра суміщаються (центр до центра); для круглих ребер – отвір і шип – осі спрямовуються однаково, а центри суміщаються.",
"Erst ein Setup anlegen.":"Спочатку створіть установку.",
"Erst ein Setup mit Operationen anlegen.":"Спочатку створіть установку з операціями.",
"Erst eine Skizze oder Konstruktionsebene wählen – dann schaut Strg+8 senkrecht darauf.":"Спершу виберіть ескіз або площину побудови – тоді Ctrl+8 дивитиметься на неї перпендикулярно.",
"Erst einen Körper in KONSTRUKTION erstellen oder ein Netz (STL) einfügen.":"Спочатку створіть тіло в КОНСТРУЮВАННІ або вставте сітку (STL).",
"Erst einen Körper in KONSTRUKTION erstellen.":"Спочатку створіть тіло в КОНСТРУЮВАННІ.",
"Erst einen Namen für das Profil eingeben.":"Спершу введіть назву профілю.",
"Erst in eine Vorlage klicken, dann den Platzhalter wählen":"Спочатку клікніть у шаблоні, потім виберіть плейсхолдер",
