"Fläche am bewegten Körper gewählt":"грань на рухомому тілі вибрано",
"Fläche anklicken – die Bohrung entsteht mit":"Клацніть грань – отвір утвориться разом з ним",
"Fläche anklicken: an jedem Klickpunkt entsteht die Durchgangsbohrung für die Schraube (ISO 273, Reihe mittel) durch alle Teile, die dort aufeinanderliegen – für Senkschrauben mit 90°-Senkung, für Zylinderschrauben auf Wunsch mit Senkbohrung (DIN 974-1, Reihe 1) so tief wie der Kopf. Die Schraube sitzt gleich darin. Bohrung und Schraube lassen sich danach im Verlauf ändern.":"Клацніть грань: у кожній позначеній точці утворюється наскрізний отвір для гвинта (ISO 273, середній ряд) крізь усі деталі, що лежать там одна на одній – для гвинтів з потайною головкою з 90° конічним зенкуванням, для гвинтів з циліндричною головкою за бажанням з циліндричним зенкуванням (DIN 974-1, ряд 1) на глибину головки. Гвинт одразу сидить в отворі. Отвір і гвинт можна згодом змінити на часовій шкалі.",
"Fläche eines Körpers anklicken: ihr Rand kommt als Kontur in die Skizze. Eine Kante anklicken projiziert nur diese Kante (Kreise bleiben Kreise). Projizierte Geometrie ist violett.":"Клікніть грань тіла: її межа потрапить в ескіз як контур. Клік на ребрі проєктує лише це ребро (кола залишаються колами). Спроєктована геометрія фіолетова.",
"Fläche ersetzen":"Замінити грань",
"Fläche ersetzen: eine ebene Fläche auf eine andere Ebene legen – der Körper wächst oder wird gekürzt":"Замінити грань: перенести плоску грань на іншу площину – тіло збільшується або скорочується",
"Fläche hinter den Fenstern – gilt, wenn oben das Design „Eigenes“ gewählt ist":"Поверхня за вікнами – діє, якщо вгорі вибрано тему «Власна»",
"Fläche löschen":"Видалити грань",
"Fläche löschen: Bohrungen, Taschen, Verrundungen oder Fasen entfernen – die Nachbarflächen schließen die Lücke":"Видалити грань: прибрати отвори, кишені, скруглення або фаски – сусідні грані закривають проміжок",
"Fläche oder Kante unter dem Mauszeiger farbig anzeigen":"Показувати грань або ребро під вказівником миші кольором",
"Fläche versetzen":"Змістити грань",
"Fläche versetzen: ebene Flächen verschieben, Bohrungen und Zapfen im Durchmesser ändern":"Змістити грань: переміщення плоских граней, зміна діаметра отворів і цапф",
"Fläche wählen":"Виберіть грань",
"Fläche wählen, die getrimmt wird":"Виберіть поверхню, яку буде обрізано",
"Fläche zum Antasten in Z":"Грань для дотику по Z",
"Fläche {0}":"Грань {0}",
"Flächen":"Грані",
"Flächen (alle Kanten ringsum)":"Грані (усі ребра навколо)",
"Flächen (aufeinander legen)":"Грані (накласти одна на одну)",
"Flächen am Körper":"Грані тіла",
"Flächen am Teilende (Zweiflach, Vierkant, Sechskant) mit einem angetriebenen Schaftfräser entlang Z. Schlüsselweite = doppelter Abstand der Fläche von der Drehachse. X und C fahren gemeinsam (Polar-Interpolation, Fanuc G12.1); ohne diese Vorlage im Postprozessor werden kurze X/C-Schritte ausgegeben.":"Грані на кінці деталі (два лиски, квадрат, шестигранник) приводною кінцевою фрезою вздовж Z. Розмір під ключ = подвійна відстань грані від осі обертання. X і C рухаються разом (полярна інтерполяція, Fanuc G12.1); без цього шаблону в постпроцесорі виводяться короткі кроки X/C.",
"Flächen anklicken, die aufgedickt werden (erneut klicken entfernt).":"Клікайте грані для додавання товщини (повторний клік скасовує вибір).",
"Flächen anklicken, die geneigt werden (erneut klicken entfernt).":"Клацніть грані, яким потрібен ухил (повторне клацання знімає вибір).",
"Flächen anklicken, die offen sein sollen.":"Клацніть грані, які мають бути відкритими.",
"Flächen anklicken, die versetzt werden (erneut klicken entfernt).":"Клікайте грані для зсуву (повторний клік скасовує вибір).",
"Flächen im Modell":"Грані в моделі",
"Flächen mit gemeinsamen Kanten werden zu einer verbunden. Ist die Hülle rundum geschlossen, entsteht ein Volumenkörper (danach normal weiterbearbeitbar). Lücken größer als die Toleranz bleiben offen.":"Поверхні зі спільними ребрами з’єднуються в одну. Якщо оболонка замкнена по всьому периметру, утворюється об’ємне тіло (далі його можна редагувати як звичайно). Проміжки більші за допуск залишаються відкритими.",
