"Fusion-360-Dateien (.f3d) sind ein geschlossenes Autodesk-Format und können nicht gelesen werden.\n\nIn Fusion 360: Datei → Exportieren → STEP (.stp) wählen und diese Datei hier importieren.":"Файли Fusion 360 (.f3d) мають закритий формат Autodesk і не можуть бути прочитані.\n\nУ Fusion 360 виберіть Файл → Експорт → STEP (.stp) та імпортуйте цей файл сюди.",
"Fusion-360-Postprozessor „{0}“ übernommen:\n\n• {1}":"Постпроцесор Fusion 360 «{0}» імпортовано:\n\n• {1}",
"Fährt alle scharfen Außenkanten ab, die von oben erreichbar sind, und bricht sie um die Entgrattiefe – mit dem Fasenfräser als Fase (Werkzeugachse senkrecht, Spitze außerhalb der Kante), mit dem Kugel-/Lollipop-Fräser gerundet.":"Проходить усіма гострими зовнішніми ребрами, доступними зверху, і притуплює їх на глибину зняття задирок – фасковою фрезою як фаску (вісь інструмента вертикальна, вістря поза ребром), кульовою/лоліпоп-фрезою – із заокругленням.",
"Führungszapfen-Ø":"Ø напрямного цапфи",
"Für 2D-Fase einen Fasenfräser (V) wählen":"Для 2D-фаски виберіть фасочну фрезу (V)",
"Für Antasten einen 3D-Taster als Werkzeug wählen":"Для вимірювання виберіть як інструмент 3D-щуп",
