"Für Setups, die nicht von oben bearbeitet werden":"Для установок, які обробляються не зверху",
"Für Sweep wird ein Pfad gebraucht: offene Linie in einer Skizze (mit Enter beenden).":"Для Sweep потрібна траєкторія: відкрита лінія в ескізі (завершіть клавішею Enter).",
"Für Touchpads: Scrollen verschiebt die Ansicht, Auseinanderziehen (oder Strg + Mausrad) zoomt":"Для тачпадів: прокручування зсуває вид, розведення пальців (або Ctrl + колесо миші) масштабує",
"Für V-Gravur einen Fasenfräser (V) wählen":"Для V-гравіювання виберіть фасочну фрезу (V)",
"Für diese Strategie nicht geeignet":"Не підходить для цієї стратегії",
"Für eine Bohrung Ø {0} mm gibt es in dieser Reihe keine passende Schraube.":"Для отвору Ø {0} mm у цьому ряду немає відповідного гвинта.",
"Für schräge Richtungen eine Konstruktionsachse anlegen (durch zwei Punkte, einen Zylinder oder zwei Ebenen) – sie erscheint dann hier als Richtung.":"Для похилих напрямків створіть допоміжну вісь (через дві точки, циліндр або дві площини) – вона з’явиться тут як напрямок.",
"Für wirbelndes Fräsen entlang einer Linie die Nutbreite angeben":"Для трохоїдального фрезерування вздовж лінії вкажіть ширину паза",
"Für {0} ist kein Gewinde hinterlegt.":"Для {0} різьбу не збережено.",
