"Gefräst wird von unten nach oben im Gleichlauf. M6 = Nenn-Ø 6, Steigung 1; M8 = 8 / 1,25; M10 = 10 / 1,5.":"Фрезерування знизу вгору, попутне. M6 = номінальний Ø 6, крок 1; M8 = 8 / 1,25; M10 = 10 / 1,5.",
"Gegenlauf":"Зустрічне",
