"Gelenkursprung: Bohrung, Zapfen oder Fläche anklicken (mehrere nacheinander möglich).":"Початок шарніра: клацніть отвір, цапфу або грань (можна кілька поспіль).",
"Gelenkursprünge ({0})":"Початки шарнірів ({0})",
"Gelenkursprünge neu wählen":"Вибрати початки шарнірів заново",
"Gemeinsame Schnittkanten nur einmal schneiden":"Спільні кромки різати лише раз",
"Gemeinsame Schnittkanten: liegen zwei Zuschnitte genau eine Schnittfuge auseinander (beim Schachteln als Abstand die Schnittfuge eintragen), fällt ihre Bahn auf der gemeinsamen Kante zusammen und wird nur einmal geschnitten. Der Anschnitt liegt nie in einem Nachbarteil: ist neben einer Kontur kein freier Abfall, wird auf der Kontur eingestochen. Nach „Vorschau“ zeigt ein Bild je Tafel die Bahn, bevor die Dateien gespeichert werden.":"Спільні кромки різу: якщо дві заготовки розташовані одна від одної рівно на ширину різу (під час розкрою вкажіть ширину різу як відстань), їхня траєкторія на спільній кромці збігається й різ виконується лише раз. Вхід у різ ніколи не лежить у сусідній деталі: якщо поруч із контуром немає вільного відходу, пробивання виконується на контурі. Після «Перегляду» зображення для кожного аркуша показує траєкторію до збереження файлів.",
"Genauigkeit":"Точність",
