"Geometriekern":"Геометричне ядро",
"Geometriekern konnte nicht geladen werden ({0}) – OpenCascade bleibt aktiv.":"Не вдалося завантажити геометричне ядро ({0}) – OpenCascade залишається активним.",
"Geometriekern: OpenCascade (über replicad) · Darstellung: three.js · Einstellungen werden auf diesem Rechner gespeichert.":"Геометричне ядро: OpenCascade (через replicad) · Відображення: three.js · Налаштування зберігаються на цьому комп'ютері.",
"Geometriekern: {0}":"Геометричне ядро: {0}",
"Georgia (Serifen)":"Georgia (із засічками)",
"Geprüft – stimmt":"Перевірено – відповідає",
"Gerade (radial)":"Пряма (радіальна)",
"Gerade Linien der Skizze, die zu keinem Profil gehören (auch Hilfslinien). Biegung: die Linie ist die Mitte der Biegezone, die Skizze dort der Zuschnitt – das größte Stück der Platte bleibt liegen, alles jenseits der Linie schwenkt mit seinen Laschen mit. Die Linie gilt über die ganze Platte. Sicke: eine Rippe entlang der Linie, im Querschnitt und an den Enden rund; das Blech behält seine Dicke.":"Прямі лінії ескіза, що не належать до жодного профілю (також допоміжні лінії). Згин: лінія – це середина зони згину, а ескіз там – заготовка; найбільша частина пластини лишається на місці, усе за лінією повертається разом зі своїми полицями. Лінія діє на всю пластину. Проштамповка: ребро вздовж лінії, кругле в перерізі й на кінцях; лист зберігає свою товщину.",
"Geraden, Bögen und Kreise":"Прямі, дуги та кола",
"Gerader Teil (nach der Biegung)":"Пряма частина (після згину)",
"Geradheit":"Прямолінійність",
