"Geschlossen (Gehrung)":"Закрито (на ус)",
"Geschlossen: Laschen an zwei Nachbarkanten laufen bis zur Winkelhalbierenden der Ecke und lassen dort den Spalt frei. Die Eckfreistellung sitzt, wo sich die Biegezonen kreuzen – in der Abwicklung und im gebogenen Teil. Auch eine Lasche an einer gebogenen Kante wird an einer echten Ecke auf Gehrung geschnitten (dort ohne Eckfreistellung).":"Закрито: лапки на двох сусідніх ребрах доходять до бісектриси кута й залишають там зазор. Розвантаження кута розташоване там, де перетинаються зони гину – на розгортці та на зігнутій деталі. Лапка на криволінійному ребрі в справжньому куті також зрізається на ус (там без розвантаження кута).",
