"Gewindebohrung im untersten Teil: die Durchgangsbohrung endet, wo das unterste Teil beginnt; dort entsteht das Kernloch mit Gewinde – drei Gewindegänge tiefer, als die Schraube reicht, oder durch das ganze Teil. Liegt nur ein Teil unter dem Punkt, bekommt es das Gewinde von der Fläche an.":"Різьбовий отвір у нижній деталі: наскрізний отвір закінчується там, де починається нижня деталь; там утворюється отвір під різьбу з різьбою – на три витки різьби глибше, ніж сягає гвинт, або крізь усю деталь. Якщо під точкою лише одна деталь, різьба в ній починається від грані.",
