"J (relativ)":"J (відносний)",
"Je Skizze die erste Kurve – offen oder geschlossen. Die Kurven werden mit einer Haut verbunden (Fläche ohne Dicke).":"Перша крива кожного ескіза – відкрита або замкнена. Криві з’єднуються оболонкою (поверхня без товщини).",
"Je Tafel eine Datei. Die Bahn läuft um die halbe Schnittfuge (beim Fräsen den halben Fräser) neben dem Umriss im Abfall; Ausschnitte kommen vor dem Umriss ihres Teils, jede Kontur beginnt mit einem Anschnitt aus dem Abfall. Kiemenschlitze werden auf ihrer Linie geschnitten. Haltestege: so viele Stellen je Umriss bleiben stehen (Laser, Plasma, Wasserstrahl: der Strahl setzt dort aus; Fräsen: der Fräser hebt auf halbe Blechdicke), Umrisse unter 40 mm Länge bekommen keine. „Steuerung“ legt fest, womit der Strahl ein- und ausgeschaltet wird; die Einstechzeit steht als G4 im Programm, außer die Steuerung sticht selbst ein. Nullpunkt ist die linke untere Ecke der Tafel, beim Fräsen Z0 die Blechoberseite. Das Programm vor dem Einsatz an der Maschine oder in einem NC-Simulator prüfen.":"Один файл на аркуш. Траєкторія проходить у відході поруч із контуром на відстані половини ширини різу (при фрезеруванні – половини фрези); вирізи йдуть перед контуром своєї деталі, кожен контур починається з входу в різ із відходу. Жалюзі вирізаються по своїй лінії. Утримувальні перемички: стільки місць на контур залишаються нерозрізаними (лазер, плазма, водяний струмінь: промінь там вимикається; фрезерування: фреза піднімається на половину товщини листа); контури коротші за 40 mm їх не мають. «Система керування» визначає, чим промінь вмикається й вимикається; час пробивання записується в програмі як G4, якщо система керування не пробиває сама. Нульова точка – лівий нижній кут аркуша, при фрезеруванні Z0 – верхня поверхня листа. Перед застосуванням перевірте програму на верстаті або в NC-симуляторі.",
"Jede Achse einzeln: Kante, Ecke, Fläche oder Bohrung anklicken. Nicht gesetzte Achsen kommen vom Rohteilpunkt.":"Кожна вісь окремо: клацніть ребро, вершину, грань або отвір. Незадані осі беруться з точки заготовки.",
"Jede Operation als Unterprogramm (LBL) am Programmende, Aufruf mit CALL LBL":"Кожна операція як підпрограма (LBL) в кінці програми, виклик через CALL LBL",
"Jeder Kreis der Skizze ist ein Bohrungsmittelpunkt. Gebohrt wird entgegen der Skizzennormalen (ins Material).":"Кожне коло ескіза є центром отвору. Свердління виконується проти нормалі ескіза (в матеріал).",
"Jeder Kreis der Skizze wird um die Mitte (in Skizzenkoordinaten) gedreht wiederholt – ein Kreis im Abstand des Teilkreisradius ergibt einen Lochkreis.":"Кожне коло ескіза повторюється з поворотом навколо центра (в координатах ескіза) – коло на відстані радіуса ділильного кола дає коло отворів.",
"Jeder Kreis der Skizze wird zum Raster: Abstände in X und Y der Skizze (auch negativ).":"Кожне коло ескіза стає сіткою: відстані по X і Y ескіза (також від’ємні).",
