"Kante {0}: Lasche an einer gebogenen Kante – ihr Rand wird beim Umformen um {1} % gestreckt (Rissgefahr); der Zuschnitt ist dort eine Näherung.":"Ребро {0}: полиця на вигнутому ребрі – її край під час формування розтягується на {1} % (ризик утворення тріщин); розгортка там є наближеною.",
"Kante {0}: das Laschenmaß {1} mm ist kleiner als die Biegung ({2} mm)":"Ребро {0}: розмір полиці {1} mm менший за згин ({2} mm)",
