"Kante {0}: die Lasche kreuzt eine Biegelinie – mit „Abstand Anfang / Ende“ vor der Biegung enden lassen":"Ребро {0}: полиця перетинає лінію згину – завершіть її перед згином за допомогою «Відступ початок / кінець»",
