"Kante {0}: ein Ausschnitt in der Lasche liegt {1} mm neben der Biegung (weniger als 2 × Blechdicke) – er verzieht sich beim Biegen.":"Ребро {0}: виріз у полиці розташований на {1} mm від згину (менше ніж 2 × товщина листа) – він деформується під час згинання.",
