"Kappe loslassen und „Nullpunkt kalibrieren“ wählen. Danach jede Richtung ausprobieren: der Balken soll sich bewegen, in Ruhe in der grauen Totzone bleiben.":"Відпустіть ковпачок і виберіть «Калібрувати нульову точку». Потім спробуйте кожен напрямок: смуга має рухатися, а в спокої залишатися в сірій мертвій зоні.",
"Kappe schieben = verschieben, drücken/ziehen = zoomen, kippen und drehen = Modell drehen. In Skizzen nur Verschieben und Zoomen. SpaceMouse Pro/Enterprise: T, F, R = Ansicht oben, vorne, rechts. Falls nichts passiert: 3Dconnexion-Treiber kurz beenden und neu verbinden.":"Зсув ковпачка = переміщення, натискання/витягування = масштабування, нахил і поворот = обертання моделі. В ескізах лише переміщення та масштабування. SpaceMouse Pro/Enterprise: T, F, R = вигляд зверху, спереду, справа. Якщо нічого не відбувається: ненадовго закрийте драйвер 3Dconnexion і підключіться знову.",
