"Kontur mit {0} Punkten – Okuma: G85 (LAP) mit Kontur G81…G80, Fanuc: G71 P…Q…. Die Steuerung schruppt mit ihrer eigenen Aufteilung; die Simulation hier ist die WerkFab-Bahn.":"Контур із {0} точок – Okuma: G85 (LAP) з контуром G81…G80, Fanuc: G71 P…Q…. Система керування виконує чорнову обробку за власним розбиттям; симуляція тут – це траєкторія WerkFab.",
"Kontur zum Freifräsen davor anlegen":"Створити контур для вибірки перед цим",
"Kontur {0}":"Контур {0}",
"Konturauswahl":"Вибір контурів",
"Konturen außen und innen":"Зовнішні та внутрішні контури",
"Konturen folgen dem Rand der dunklen Flächen. Die Mittellinie läuft in der Mitte der Striche – passend für Gravuren und Strichzeichnungen. „Geraden, Bögen und Kreise“ erkennt gerade Kanten, scharfe Ecken, Rundungen und Kreise; „Linienzüge“ folgt dem Bild Punkt für Punkt. Den Maßstab danach bei Bedarf mit „Vorlage kalibrieren“ oder „Skalieren“ anpassen.":"Контури йдуть по краю темних областей. Осьова лінія проходить посередині штрихів – підходить для гравірування та штрихових малюнків. «Прямі, дуги та кола» розпізнає прямі краї, гострі кути, заокруглення та кола; «Полілінії» повторюють зображення точка за точкою. За потреби потім підлаштуйте масштаб через «Калібрувати шаблон» або «Масштабувати».",
"Konturen mit Radiuskorrektur an der Steuerung (RL/RR) fahren mit APPR/DEP an und ab; die Steuerung berechnet Hilfspunkt und Korrektur selbst":"Контури з корекцією радіуса в системі керування (RL/RR) заходять і виходять через APPR/DEP; система керування сама обчислює допоміжну точку та корекцію",
