"Kurven":"Криві",
"Kurven einer Skizze auf der Planfläche (quer zur Drehachse) mit einem angetriebenen Fräser entlang Z (X und C fahren gemeinsam; Fanuc: Polar-Interpolation G12.1). Offene Kurven werden hin und zurück gefräst. Tiefe ab Planfläche.":"Криві ескіза на торці (поперек осі обертання) приводною фрезою вздовж Z (X і C рухаються разом; Fanuc: полярна інтерполяція G12.1). Розімкнені криві фрезеруються туди й назад. Глибина від торця.",
"Kurven einer Skizze, die längs zur Drehachse liegt, werden auf den Umfang gewickelt und mit einem angetriebenen Fräser gefräst, der zur Achse zeigt (Z und C fahren gemeinsam; Fanuc: Zylinder-Interpolation G7.1). Die Skizzenebene bestimmt den Winkel, an dem die Kontur sitzt; waagerechte Strecken in der Skizze werden Bögen um das Teil. Tiefe ab Außendurchmesser.":"Криві ескіза, що лежить уздовж осі обертання, навиваються на окружність і фрезеруються приводною фрезою, спрямованою до осі (Z і C рухаються разом; Fanuc: циліндрична інтерполяція G7.1). Площина ескіза визначає кут, під яким розташований контур; горизонтальні відрізки ескіза стають дугами навколо деталі. Глибина від зовнішнього діаметра.",
"Kurzbefehl":"Комбінація клавіш",
"Kurze Wege (bis zum Halteabstand) fährt das Werkzeug unten im Übergangsvorschub statt über die Rückzugshöhe – ohne Kollisionsprüfung, daher klein halten.":"Короткі переміщення (до відстані утримання) інструмент виконує внизу з подачею переходу замість підйому на висоту відведення – без перевірки зіткнень, тому тримайте значення малим.",
