"Mit diesem Werkzeug kann nicht gefräst werden":"Цим інструментом фрезерувати не можна",
"Mit einem Gewindebohrer nur Zyklus „Gewindebohren“ – ein Bohrzyklus würde ihn abbrechen":"З мітчиком лише цикл «Нарізання різьби мітчиком» – цикл свердління зламав би його",
"Mit mehreren Zustellungen wird die Gewindetiefe in Schritten gefräst, die jeweils etwa gleich viel abnehmen – schont kleine Gewindefräser und harte Werkstoffe. Der Leerdurchgang fährt die letzte Bahn noch einmal ohne Zustellung.":"За кількох врізань глибина різьби фрезерується кроками, що знімають приблизно однаково, – це щадить малі різьбові фрези й тверді матеріали. Холостий прохід ще раз проходить останню траєкторію без врізання.",
"Mit „Bohrzyklen“ im NC-Programm werden Steuerungszyklen ausgegeben (G81–G86, Heidenhain CYCL 200–207, Sinumerik CYCLE81–85), sonst ausgeschriebene Bewegungen.":"З опцією «Цикли свердління» в NC-програмі виводяться цикли системи керування (G81–G86, Heidenhain CYCL 200–207, Sinumerik CYCLE81–85), інакше – розгорнуті переміщення.",
"Mit „Original behalten“ werden Original und Spiegelbild ein Netz; Punkte auf der Spiegelebene werden verbunden – aus einer offenen Hälfte wird so ein geschlossenes Teil.":"З «Зберегти оригінал» оригінал і дзеркальне відображення стають однією сіткою; точки на площині дзеркала з’єднуються – з відкритої половини виходить замкнена деталь.",
