"Nur das bearbeiten, was ein größerer Fräser in Ecken stehen gelassen hat.":"Обробляти лише те, що більша фреза залишила в кутах.",
"Nur die Stellen der Kontur nachfahren, die ein größerer Fräser nicht erreicht hat (Innenecken, enge Stellen). Ohne An-/Abfahrbögen, Haltestege und Schlichtdurchgänge; Korrektur im Rechner.":"Проходити лише ті ділянки контуру, яких не досяг більший різець (внутрішні кути, вузькі місця). Без дуг входу/виходу, перемичок і чистових проходів; корекція в комп’ютері.",
"Nur dort, wo das Referenzwerkzeug nicht hinkam: flache Bereiche parallel, steile Bereiche als Wasserlinie. Mit einem Werkzeug aus der Liste zählt dessen Form mit – zum Beispiel was ein Torusfräser in den Hohlkehlen stehen lässt.":"Лише там, куди опорний інструмент не дістав: пологі ділянки паралельно, круті – за ватерлінією. З інструментом зі списку враховується і його форма – наприклад, те, що торова фреза залишає в галтелях.",
"Nur ebene Flächen können als Skizzenebene dienen.":"Площиною ескіза можуть бути лише плоскі грані.",
"Nur ebene Flächen können extrudiert werden":"Витискати можна лише пласкі грані",
"Nur ebene Flächen lassen sich ersetzen":"Замінювати можна лише пласкі грані",
"Nur ebene Flächen und Zylinderflächen (Bohrungen, Zapfen) lassen sich versetzen":"Зміщувати можна лише пласкі та циліндричні грані (отвори, цапфи)",
"Nur ebene Flächen, die nach oben zum Werkzeug zeigen (waagerecht in diesem Setup).":"Лише плоскі грані, спрямовані вгору до інструмента (горизонтальні в цій установці).",
"Nur für Außen-Drehmeißel":"Лише для зовнішніх токарних різців",
"Nur in Operationen verwendete":"Лише використовувані в операціях",
"Nur in diesem Projekt":"Лише в цьому проєкті",
"Nur mit Korrektur „Im Rechner“.":"Лише з корекцією «У комп’ютері».",
"Nur stärkste Achse":"Лише найсильніша вісь",
"Nut":"Паз",
"Nut angetrieben":"Паз приводним інструментом",
"Nut angetrieben (C-Achse)":"Паз приводним інструментом (вісь C)",
"Nut liegt nicht am Teil":"Паз не лежить на деталі",
"Nut längs der Drehachse (z. B. Passfedernut) mit einem angetriebenen Fräser, der zur Achse zeigt; die Hauptspindel hält das Teil als C-Achse. Nutbreite = Fräser-Ø. Start/Ende Z in Modell-Z; reicht die Nut bis zur Planfläche, fährt der Fräser von vorn ein, sonst taucht er am Start ein. Tiefe ab Außendurchmesser.":"Паз уздовж осі обертання (напр. шпонковий) приводною фрезою, спрямованою до осі; головний шпиндель утримує деталь як вісь C. Ширина паза = Ø фрези. Початок/кінець Z у Z моделі; якщо паз сягає торця, фреза входить спереду, інакше врізається на початку. Глибина від зовнішнього діаметра.",
"Nutbreite bei Linien":"Ширина паза для ліній",
