"Offene Flächen":"Відкриті грані",
"Offene Kanten werden rot angezeigt. „Reparieren“ schließt Löcher.":"Відкриті ребра показано червоним. «Відновити» закриває отвори.",
"Offene Linie in einer Skizze wählen":"Виберіть відкриту лінію в ескізі",
"Offene oder geschlossene Kurven werden senkrecht zur Skizze gezogen – es entsteht eine Fläche (Wand ohne Dicke). Mit „Aufdicken“ oder „Zusammenfügen“ wird daraus ein Volumen.":"Відкриті або замкнені криві витягуються перпендикулярно до ескіза – утворюється поверхня (стінка без товщини). Через «Надати товщину» або «Зшити» з неї виходить об’ємне тіло.",
"Offene oder geschlossene Kurven werden um die Achse gedreht – es entsteht eine Fläche, kein Volumen.":"Відкриті або замкнені криві обертаються навколо осі – утворюється поверхня, а не об’єм.",
"Ohne Mutter":"Без гайки",
"Ohne eigene Taste gilt der Standard „{0}“.":"Без власної клавіші діє стандартна «{0}».",
"Ohne „Modelliert“ wird das Gewinde nur dargestellt (schnell). Modelliert wird die Gewindeform wirklich ausgeschnitten, z. B. für 3D-Druck. Bohrung für M8 = Ø6,8.":"Без опції «Змодельована» різьба лише відображається (швидко). Якщо змодельована, профіль різьби дійсно вирізається, напр. для 3D-друку. Отвір для M8 = Ø6,8.",
"Okuma OSP Drehen":"Okuma OSP точіння",
"Okuma OSP-M Fräsen":"Okuma OSP-M фрезерування",
"Okuma OSP: G28/G53 fahren dort nicht auf Maschinenkoordinaten (G53 hebt die Werkzeuglängenkorrektur auf) – Rückzug auf Sicherheitshöhe, keine XY-Referenzfahrt ausgegeben":"Okuma OSP: G28/G53 там не виконують виїзд у координати верстата (G53 скасовує корекцію довжини інструмента) – відведення на безпечну висоту, XY-референтний виїзд не виведено",
"Okuma OSP: keine Glättungsfunktion ausgegeben (G5.1 ist Fanuc) – Hi-Cut/Super-NURBS an der Maschine einstellen":"Okuma OSP: функцію згладжування не виведено (G5.1 – це Fanuc) – налаштуйте Hi-Cut/Super-NURBS на верстаті",
"Okuma: Korrektur+Werkzeug+Schneide (z. B. 010101)":"Okuma: корекція+інструмент+різальна кромка (напр. 010101)",
"OpenCascade (alle Funktionen)":"OpenCascade (усі функції)",
"OpenCascade: alle Funktionen. Rust-Kern (truck, experimentell): Grundkörper, Extrusion, Rotation, Bohrung, Muster, Spiegeln, Verschieben, Skalieren, Kombinieren und STEP-Export – andere Features werden als „noch nicht unterstützt“ markiert.":"OpenCascade: усі функції. Ядро на Rust (truck, експериментальне): базові тіла, витискання, обертання, отвір, масив, дзеркало, переміщення, масштабування, об'єднання та експорт STEP – інші елементи позначаються як «ще не підтримується».",
