"Projizieren (J): Fläche oder Kante eines Körpers anklicken – ihr Abbild kommt in die Skizze":"Проєктувати (J): клацніть грань або ребро тіла – їхня проєкція потрапить в ескіз",
"Projizieren von Kanten und Flächen braucht einen Volumenkörper des Standardkerns – Körperumriss und Schnittkurven gehen auch bei Netzen.":"Для проєціювання ребер і граней потрібне об'ємне тіло стандартного ядра – обрис тіла та криві перетину працюють і для сіток.",
"Projizieren: Fläche oder Kante eines Körpers anklicken.":"Проєціювання: клацніть грань або ребро тіла.",
"Projizierte Fläche: folgt dem Körper, wenn er sich ändert.":"Спроєктована грань: слідує за тілом, коли воно змінюється.",
"Projizierte Kante: folgt dem Körper, wenn er sich ändert.":"Спроєктоване ребро: слідує за тілом, коли воно змінюється.",
"Projizierter Körperumriss: folgt dem Körper, wenn er sich ändert.":"Спроєктований обрис тіла: слідує за тілом, коли воно змінюється.",
"Präfix":"Префікс",
