"Prägung":"Тиснення",
"Prägung {0}: die Kontur ist schmaler als 2 × Blechdicke – es bleibt kein Hohlraum.":"Тиснення {0}: контур вужчий за 2 × товщину листа – порожнини не залишиться.",
"Prägung {0}: lässt sich so nicht formen":"Тиснення {0}: так сформувати неможливо",
"Prägung {0}: mit dieser Wandschräge lässt sie sich nicht formen":"Тиснення {0}: з таким кутом стінки сформувати неможливо",
"Prägung {0}: {1} mm ist höher als 3 × Blechdicke – mit senkrechter Wand reißt das Blech.":"Тиснення {0}: {1} mm більше за 3 × товщину листа – при вертикальній стінці лист розірветься.",
"Prägung: die Kontur wird nicht ausgeschnitten, sondern um die Höhe aus der Platte gedrückt; das zweite Feld ist die Wandschräge (0° = senkrecht). Senkprägung: der Rand einer runden Bohrung wird zu einem 90°-Kegel gedrückt – für Senkschrauben in dünnem Blech (− nach unten: Schraube von oben).":"Тиснення: контур не вирізається, а видавлюється з листа на задану висоту; друге поле – кут стінки (0° = вертикально). Тиснення під зенківку: край круглого отвору видавлюється в 90°-конус – для гвинтів із потайною головкою в тонкому листі (− вниз: гвинт зверху).",
