"Tasche Planfläche (C-Achse)":"Кишеня на торці (вісь C)",
"Tasche auf dem Umfang aus den geschlossenen Konturen einer Skizze, die längs zur Drehachse liegt (innere Konturen bleiben als Inseln stehen). Die Skizze wird auf den Durchmesser gewickelt; ein angetriebener Schaftfräser, der zur Achse zeigt, räumt von innen nach außen (Z und C fahren gemeinsam; Fanuc: Zylinder-Interpolation G7.1). Der Fräser taucht auf einer Rampe entlang des innersten Rings ein.":"Кишеня на колі з замкнених контурів ескіза, що лежить уздовж осі обертання (внутрішні контури залишаються острівцями). Ескіз навивається на діаметр; приводна кінцева фреза, спрямована до осі, вибирає матеріал зсередини назовні (Z і C рухаються разом; Fanuc: циліндрична інтерполяція G7.1). Фреза врізається по рампі вздовж найвнутрішнього кільця.",
"Tasche in der Planfläche aus den geschlossenen Konturen einer Skizze (innere Konturen bleiben als Inseln stehen), mit einem angetriebenen Schaftfräser entlang Z. Geräumt wird von innen nach außen; der Fräser taucht auf einer Rampe entlang der innersten Bahn ein und bleibt innerhalb einer Ebene unten. X und C fahren gemeinsam (Fanuc: Polar-Interpolation G12.1). Tiefe ab Planfläche.":"Кишеня в торці із замкнених контурів ескіза (внутрішні контури залишаються островами) приводною кінцевою фрезою вздовж Z. Вибирання йде зсередини назовні; фреза врізається по рампі вздовж найвнутрішнього проходу й залишається внизу в межах одного рівня. X і C рухаються разом (Fanuc: полярна інтерполяція G12.1). Глибина від торця.",
"Tasche mit Insel – der Steuerungszyklus kann keine Inseln":"Кишеня з островом – цикл системи керування не підтримує острови",
