"Vernetzung fehlgeschlagen:":"Не вдалося створити сітку:",
"Verrechnet zwei geschlossene Netze wirklich miteinander: innen liegende Flächen verschwinden, die Schnittkanten werden neu vernetzt. Gerechnet wird nur dort, wo sich die beiden Netze begegnen können – ein großes Netz mit einem kleinen Eingriff geht deshalb schnell. Überlappen zwei große Netze ganz, vorher „Reduzieren“.":"Справді обчислює дві замкнені сітки одна з одною: внутрішні поверхні зникають, ребра перетину створюються заново. Обчислення відбувається лише там, де обидві сітки можуть зустрітися, тому велика сітка з невеликим втручанням обробляється швидко. Якщо дві великі сітки перекриваються повністю, спершу «Зменшити».",
