"Verschleiß":"Знос",
"Verschraubung: Scheiben und Mutter kommen mit der Schraube in einem Zug an jede angeklickte Bohrung. Die Klemmdicke ist die Länge der Bohrung – durch mehrere Teile hindurch, wenn ihre Bohrungen fluchten und aneinanderstoßen. Mit Mutter wird die kürzeste Vorzugslänge vorgeschlagen, bei der die Schraube zwei Gewindegänge aus der Mutter ragt.":"Гвинтове з’єднання: шайби та гайка встановлюються разом із гвинтом за один раз на кожен вибраний отвір. Товщина пакета – це довжина отвору, крізь кілька деталей, якщо їхні отвори співвісні й прилягають одна до одної. З гайкою пропонується найкоротша переважна довжина, за якої гвинт виступає з гайки на два витки різьби.",
"Verschraubung: {0} – Klemmdicke {1} mm":"Гвинтове з’єднання: {0} – товщина пакета {1} mm",
