"Verschraubung: {0} – {1}; die Schraube ist für die Klemmdicke {2} mm zu kurz (nötig: {3} mm)":"Гвинтове з’єднання: {0} – {1}; гвинт закороткий для товщини пакета {2} mm (потрібно: {3} mm)",
