"Wickelt die Skizzenkurven auf den Zylinder: X bleibt X, der Abstand quer zur Achse wird zum Bogen auf dem Abwicklungs-Ø (Drehung A). Die Skizze muss parallel zur A-Achse liegen, z. B. auf einer Tangentialebene. Gefräst wird in fester Tiefe unter der Teiloberfläche – für Gravuren, Schriften und Nuten rund um das Teil.":"Навиває криві ескіза на циліндр: X залишається X, відстань поперек осі стає дугою на Ø розгортки (обертання A). Ескіз має лежати паралельно осі A, напр. на дотичній площині. Фрезерування на сталій глибині під поверхнею деталі – для гравіювання, написів і пазів навколо деталі.",
"Wie 3D-Kontur, aber das Werkzeug fährt ohne Absätze kontinuierlich nach unten – keine Eintauchmarken an steilen Wänden.":"Як 3D-контур, але інструмент безперервно опускається без уступів – без слідів врізання на крутих стінках.",
