"{0}: 4-Achs-Simultan – Maschine mit Drehachse A wählen":"{0}: 4-осьова одночасна обробка – виберіть верстат з віссю обертання A",
"{0}: Bohrzyklus nicht möglich (Tiefe 0) – als Bahn ausgegeben":"{0}: Цикл свердління неможливий (глибина 0) – виведено як траєкторію",
