"{0}: Dieser Postprozessor hat keine Vorlage für die Verweilzeit – übersprungen":"{0}: Цей постпроцесор не має шаблону для витримки – пропущено",
"{0}: Dieser Postprozessor hat keinen Tastzyklus für „{1}“ – übersprungen":"{0}: Цей постпроцесор не має циклу вимірювання щупом для «{1}» – пропущено",
"{0}: Drehzahl {1} > Maschinenmaximum {2} – begrenzt":"{0}: Частота обертання {1} > максимум верстата {2} – обмежено",
"{0}: Ecke anklicken – Linienzug, Rechteck oder Treffpunkt zweier Linien. Das Werkzeug bleibt aktiv, Esc beendet.":"{0}: клацніть кут – полілінія, прямокутник або точка перетину двох ліній. Інструмент залишається активним, Esc завершує.",
"{0}: Fläche oder Kante im Modell anklicken.":"{0}: клацніть грань або ребро на моделі.",
"{0}: GRBL kennt keine Radiuskorrektur (G41/G42) – Bahn ohne Korrektur ausgegeben":"{0}: GRBL не підтримує корекцію радіуса (G41/G42) – траєкторію виведено без корекції",
"{0}: Nullpunkt Y/Z liegt nicht auf der Drehachse A (Achse bei Y{1} Z{2}) – für 4-Achs-Simultan den Nullpunkt auf die Achse legen (Rohteil-Punkt Mitte Y/Z)":"{0}: нульова точка Y/Z не лежить на осі обертання A (вісь при Y{1} Z{2}) – для 4-осьової одночасної обробки помістіть нульову точку на вісь (точка заготовки: центр Y/Z)",
"{0}: Postprozessor ohne Drehzyklus – als Bahn ausgegeben":"{0}: Постпроцесор без циклу точіння – виведено як траєкторію",
"{0}: Postprozessor ohne Polar-Interpolation – Flächen als kurze X/C-Schritte (C in Grad) ausgegeben; der Vorschub gilt dann je nach Steuerung nicht entlang der Bahn. Besser die Vorlage „Polar-Interpolation ein/aus“ eintragen":"{0}: постпроцесор без полярної інтерполяції – грані виведено як короткі кроки X/C (C у градусах); залежно від системи керування подача тоді діє не вздовж траєкторії. Краще заповнити шаблон «Полярна інтерполяція вкл/викл»",
"{0}: Postprozessor ohne Vorlage „C-Achse und angetriebenes Werkzeug ein“ – C-Achse und Werkzeugspindel von Hand einschalten":"{0}: Постпроцесор без шаблону «C-вісь та приводний інструмент увімк.» – увімкніть вісь C і шпиндель інструмента вручну",
"{0}: Postprozessor ohne Zylinder-Interpolation – Z und C fahren gemeinsam, der Vorschub gilt dann je nach Steuerung nicht entlang der Bahn. Besser die Vorlage „Zylinder-Interpolation ein/aus“ eintragen":"{0}: постпроцесор без циліндричної інтерполяції – Z і C рухаються разом; залежно від системи керування подача тоді діє не вздовж траєкторії. Краще заповнити шаблон «Циліндрична інтерполяція вкл/викл»",
"{0}: Postprozessor ohne {1} für diese Form – als Bahn ausgegeben":"{0}: Постпроцесор без {1} для цієї форми – виведено як траєкторію",
"{0}: Schlichtzyklus folgt der Hüllkontur – Hinterschnitt/Einstich bleibt stehen":"{0}: цикл чистової обробки йде по огинальному контуру – підріз/канавка залишається",
"{0}: Schlichtzyklus fährt die Fertigkontur – Aufmaß {1} mm wird nicht berücksichtigt":"{0}: цикл чистової обробки йде по готовому контуру – припуск {1} мм не враховується",
"{0}: Schlichtzyklus nicht möglich ({1}) – als Bahn ausgegeben":"{0}: цикл чистової обробки неможливий ({1}) – виведено як траєкторію",
"{0}: Steuerung/Postprozessor ohne Gewindebohrzyklus – als Vorschubbewegung ausgegeben (nur mit Ausgleichsfutter!)":"{0}: система керування/постпроцесор без циклу нарізання різьби мітчиком – виведено як рух із подачею (лише з компенсаційним патроном!)",
"{0}: Steuerungszyklus nicht möglich (Tiefe 0) – als Bahn ausgegeben":"{0}: Цикл системи керування неможливий (глибина 0) – виведено як траєкторію",
