"„+“ = Werkzeug wird neu angelegt. Schnittdaten sind Richtwerte für Hartmetall ({0}){1}; Kühlung: {2}.":"«+» = інструмент буде створено заново. Режими різання є орієнтовними значеннями для твердого сплаву ({0}){1}; охолодження: {2}.",
"„Ineinander schachteln“ legt die Zuschnitte in die Lücken und Buchten ihrer Nachbarn und in deren Ausschnitte (ohne 90°-Drehen nur um 180° gewendet); der Abstand wird nie unterschritten. Ohne den Haken liegen sie nach ihrem umschließenden Rechteck in Reihen. Mit „Skizze + Körper“ entstehen flache Körper in Blechdicke, die sich in der Fertigung mit 2D-Kontur ausschneiden lassen.":"«Вкладати одну в одну» розкладає заготовки в проміжки та виїмки сусідніх деталей і в їхні вирізи (без повороту на 90° лише перевернуті на 180°); відстань ніколи не порушується. Без позначки вони лежать рядами за своїм описаним прямокутником. З «Ескіз + тіла» утворюються пласкі тіла завтовшки з лист, які у виробництві можна вирізати за 2D-контуром.",
"„Innen/Außen“ braucht geschlossene Konturen – offene Kurven mit „Auf der Kurve“ fräsen":"«Всередині/зовні» потребує замкнених контурів – відкриті криві фрезеруйте з «По кривій»",
