"⚠ Programmlogik (JavaScript) wird nicht ausgeführt: Sonderfunktionen, 4./5. Achse, Messzyklen und Maschinenoptionen bitte im Postprozessor-Editor prüfen.":"⚠ Логіка програми (JavaScript) не виконується: перевірте спеціальні функції, 4-ту/5-ту вісь, цикли вимірювання та опції верстата в редакторі постпроцесора.",
