"📚 = Bibliothek: eigene Postprozessoren stehen in allen Projekten zur Verfügung. Ein verwendeter wird ins Projekt kopiert, damit die Datei vollständig bleibt.":"📚 = бібліотека: власні постпроцесори доступні в усіх проєктах. Використаний постпроцесор копіюється в проєкт, щоб файл залишався повним.",
